<?php
namespace App\Services; use App\Models\Quartier; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Http; use RuntimeException;
class OpenMeteoService { public function weather(Quartier $quartier): array { return Cache::remember("open-meteo:{$quartier->id}", now()->addMinutes(10), function() use($quartier){ try {$response=Http::timeout(8)->get('https://api.open-meteo.com/v1/forecast',['latitude'=>$quartier->latitude,'longitude'=>$quartier->longitude,'current'=>'temperature_2m','daily'=>'temperature_2m_max,temperature_2m_min','timezone'=>'Africa/Tunis']); if(!$response->successful()) throw new RuntimeException(); $data=$response->json(); $temp=data_get($data,'current.temperature_2m');$max=data_get($data,'daily.temperature_2m_max.0');$min=data_get($data,'daily.temperature_2m_min.0');if(!is_numeric($temp)||!is_numeric($max)||!is_numeric($min))throw new RuntimeException(); return ['temperature'=>(float)$temp,'temperature_max'=>(float)$max,'temperature_min'=>(float)$min];}catch(\Throwable){throw new RuntimeException('Les données météo sont temporairement indisponibles.');} }); } }
